import json,hashlib,re
p='/workspace/scratch/volume4/batch499-508.json';x=json.load(open(p))
for pg in x['pages']:
 for s in pg['paragraphs']:
  s['ar']=s['ar'].replace('فهذا ليست شرطا','فهذه ليست شرطا')
  if pg['printed_page']==502:s['ar']=s['ar'].replace('[يس: 22–23]','[يس: 23]')
  if pg['printed_page']==508:s['ar']=s['ar'].replace('ورجلا سلما لرجل','ورجلا سَالِمًا لرجل')
  s['sha256']=hashlib.sha256(s['ar'].encode()).hexdigest()
lookup={s['id']:s['ar'] for pg in x['pages'] for s in pg['paragraphs']}
for u in x['units']:
 u['ar']=' '.join(lookup[s] for s in u['source_ids'])
 u['ru']=u['ru'].replace('ورجلا سلما لرجل','ورجلا سَالِمًا لرجل').replace('В Коране таких ясных знамений — более десятков тысяч.','Таких ясных знамений в Коране — десятки тысяч и более.').replace('поэтому за оставление этого человек не заслуживает наказания','поэтому на основании одного разума человек не заслуживает наказания за его оставление')
 if u['id']=='v4-p500-01-ru':u['ru']+='»'
 if u['id']=='v4-p503-05-ru':u['ru']=u['ru'].replace('Наш шейх сказал: „','Наш шейх сказал: «').replace('запретил“.','запретил».')
 u['draft_status']='self_reviewed'
x['boundary_notes']=[{'printed_page':499,'side':'start','note':'498 реально просмотрена для контекста: последний абзац с23:51–52 завершён.499 начинается новым абзацем21:25; слияния498/499 не требуется.'},{'printed_page':508,'side':'end','source_id':'v4-p508-04','note':'Обязательный открытый перенос внутри22:74 и авторского абзаца:508 заканчивается «إن الله لقوي»,509 начинается «عزيز} [الحج:73] إلى أضعاف أضعاف ذلك من براهين التوحيد العقلية التي أرشد إليها القرآن ونبه عليها».509 реально просмотрена, но не импортирована. По указанию родителя искусственная закрывающая} не добавлена. RU содержит перевод имеющейся части, затем открытыйAR-фрагмент; при объединении508/509 нужно перестроить эту последнюю цитату в обычный порядокAR/перевод/ссылка, добавить смысл «Могущественный» и заключение авторского абзаца. Все source_ids и AR должны объединяться одним пробелом.'},{'printed_pages':[500,501],'note':'Открытая на500 кораническая цитата39:64–66 замкнута на501 и объединена в v4-p500-06-ru; полная арабская цитата повторена вRU.'},{'printed_pages':[503,504],'note':'Слита цитата шейха о двух خليل и полноте единобожия.'},{'printed_pages':[504,505],'note':'Слит перенос аргумента «فلو كان / شيء أعظم...».'},{'printed_pages':[506,507],'note':'Слит перенос характеристики здравого сердца и противостоящих велению желаний.'}]
x['review_notes']=[{'type':'source_collation','pages':list(range(499,509)),'note':'Первый фактический проход: все10 страниц прочитаны по рендерам1800px;498 и509 просмотрены только для контекста. Второй просмотр всех10 изображений выполнен при обратной сверке.505 и508 дополнительно просмотрены при2600px; фрагмент50839:29 увеличен отдельным кропом для чтения سَالِمًا. Издательские сноски и маркеры исключены.'},{'type':'semantic_back_comparison','pages':list(range(499,509)),'note':'Второй фактический проход: сопоставлены AR/RU со всеми повторно просмотренными страницами. Все коранические серии499–503 и508 переданы целиком в пределах страниц, включая отрицание/утверждение500, фана/пребывание и все формы поклонения; длинная26:69–82 не сокращена. Сохранены приоритет единобожия пророков503–504, все аргументы о доказательствах504–506, согласие сердца/языка507 и обе позиции об обязанности и наказании507–508 вместе с авторским выводом. На505 исправлен ручной набор «فهذا ليست» на фактически печатное «فهذه ليست».'},{'type':'russian_only_reading','pages':list(range(499,509)),'note':'Третий фактический проход: весьRU прочитан отдельно. Устранено незамкнутое русское цитирование500, унифицированы кавычки цитаты503–504; сглажено «десятки тысяч и более»506, где речь о знамениях/доказательствах, а не числе аятов;508 уточнён контекст наказания на основании одного разума. Арабские фигурные цитаты проверены на тождество вRU, включая намеренно открытый внешний фрагмент508. Поэтических строк в этом диапазоне нет.'},{'type':'print_question','pages':[499,501,502,503,508],'note':'49921:25 сохранено печатное يُوحَى сياء, не заменено на نوحي.50839:29 сохранено сَالِمًا сألف; чтение подтверждено увеличением, не приведено к سلمًا. Печатные ссылки501 «الزمر:64–65»,502 «يس:23» и503 «الزخرف:26» оставлены вAR, хотя цитируемые фрагменты охватывают соответственно39:64–66,36:22–23 и43:26–27; вRU даны фактические диапазоны. Внешняя ссылка22:73 напечатана уже на509, хотя заканчивается74: учитывать приmerge.'},{'type':'uncertainty','pages':[500,503,505,507,508],'note':'Самостоятельная проверка не равна независимой человеческой/богословской экспертизе. خليلان переданы «двое возлюбленных Аллаха» (Ибрахим и Мухаммад по контексту); ذمة505 — обязательная защита, не автоматически современное гражданство; سمع507–508 — услышанное откровение, не слух как способность. Открытая структура последнего блока508 заведомо требует внешнегоmerge с509 прежде публикационной проверки.'}]
used=[]
for pg in x['pages']:
 assert pg['paragraphs']
